import {CAPACITY,infer,book,validateReading,closeCase} from './core.mjs';
import {progress,visitState} from './presentation.mjs';
const $=s=>document.querySelector(s);
const icons={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',house:'M3 11 12 3l9 8 M5 10v11h14V10 M9 21v-7h6v7',calendar:'M4 5h16v16H4z M7 3v4 M17 3v4 M4 10h16 M8 14h2 M14 14h2',activity:'M2 12h5l3-8 4 16 3-8h5',info:'M12 8h.01 M12 11v6 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',reset:'M3 10a9 9 0 1 1 1 7 M3 4v6h6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',check:'M5 12l4 4L19 6',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',alert:'M12 3 2 21h20L12 3z M12 9v5 M12 17h.01',drop:'M12 2C10 6 4 11 4 15a8 8 0 0 0 16 0c0-4-6-9-8-13z M8 15a4 4 0 0 0 4 4',close:'M6 6l12 12 M18 6 6 18',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7z M8 12l3 3 5-6',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6'};
const icon=(name)=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
function decorate(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}
decorate();let model,scenarios,state,page='panel',selected='H-03',filter='all',toastTimer;
const labels={alert:'Posible fuga · por revisar',normal:'Sin patrón inusual',insufficient:'Datos insuficientes',stale:'Lecturas desactualizadas',review:'Revisión humana',scheduled:'Visita programada',visited:'Falta verificar',verified:'Cierre verificado',funding:'Pendiente de apoyo'};
const descriptions={alert:'La señal indica un patrón inusual. Una persona debe revisar el contexto antes de decidir.',normal:'No se detectó un patrón inusual en estos datos sintéticos. Esto no confirma que el hogar esté libre de fugas.',insufficient:'Faltan lecturas para evaluar el patrón. Pide una serie completa o una revisión manual.',stale:'Las lecturas no están actualizadas. No se ejecutó el modelo con estos datos.'};
const stages=['Señal','Revisión','Visita','Verificación'];
function makeState(){return {used:0,ended:false,bookings:[],cases:Array.from({length:12},(_,i)=>{const id=`H-${String(i+1).padStart(2,'0')}`,scenario=i===1?'normal':i===3?'insufficient':'leak';return {id,scenario,values:[...scenarios[scenario]],updatedAt:Date.now(),stage:'new',appointment:null,manual:[],history:[{at:Date.now(),text:'Caso ficticio cargado. Pendiente de revisión humana.'}]}})}}
function ccase(){return state.cases.find(c=>c.id===selected)}
function signal(c){return infer(c.values,model,c.updatedAt)}
function status(c){return c.stage==='new'?signal(c).kind:c.stage}
function badge(c){const s=status(c);return `<span class="badge ${s}">${labels[s]}</span>`}
function log(c,text){c.history.unshift({at:Date.now(),text})}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function go(next){page=next;location.hash=next;render();window.scrollTo({top:0,behavior:'smooth'})}
function chart(values){const w=630,h=182,left=38,right=12,top=13,bottom=28;let good=values.filter(Number.isFinite),max=Math.max(10,...good)*1.15;let path='',area='',prev=false;values.forEach((v,i)=>{if(!Number.isFinite(v)){prev=false;return}const x=left+i*(w-left-right)/95,y=top+(1-v/max)*(h-top-bottom);path+=`${prev?'L':'M'}${x.toFixed(1)},${y.toFixed(1)} `;prev=true});if(values.every(Number.isFinite)){area=path+`L${w-right},${h-bottom} L${left},${h-bottom} Z`}return `<svg class="chart" role="img" aria-label="Consumo simulado durante 24 horas, en litros por intervalo de 15 minutos" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#087e7b" stop-opacity=".13"/><stop offset="1" stop-color="#087e7b" stop-opacity=".01"/></linearGradient></defs>${[0,.25,.5,.75,1].map(n=>{let y=top+(1-n)*(h-top-bottom);return `<line x1="${left}" x2="${w-right}" y1="${y}" y2="${y}" stroke="#e9efeb"/><text x="${left-8}" y="${y+3}" text-anchor="end">${Math.round(n*max)}</text>`}).join('')}${[0,4,8,12,16,20,24].map((n,i)=>`<text x="${left+i*(w-left-right)/6}" y="${h-6}" text-anchor="middle">${String(n===24?0:n).padStart(2,'0')}:00</text>`).join('')}<path d="${area}" fill="url(#fill)"/><path d="${path}" stroke="#168982" stroke-width="2.2" fill="none" vector-effect="non-scaling-stroke"/></svg>`}
function heading(title,sub,action='manual'){return `<div class="page-heading"><div><div class="eyebrow">VISIBILIDAD QUE SE CONVIERTE EN ACCIÓN</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action?`<button class="btn primary" data-action="${action}">${icon('plus')}${action==='manual'?'Registrar lectura':'Ver límites'}</button>`:''}</div>`}
function stats(){const alerts=state.cases.filter(c=>['alert','insufficient','stale','review'].includes(status(c))).length,verified=state.cases.filter(c=>c.stage==='verified').length;return `<div class="stats"><div class="stat"><div class="stat-top">Hogares en el piloto ${icon('house')}</div><div class="number">12 <small>hogares</small></div><div class="stat-foot">Todos los datos son ficticios</div></div><div class="stat"><div class="stat-top">Pendientes de revisión ${icon('activity')}</div><div class="number">${String(alerts).padStart(2,'0')}</div><div class="stat-foot"><span class="dot"></span>Necesitan una mirada humana</div></div><div class="stat featured"><div class="stat-top">Citas disponibles ${icon('calendar')}</div><div class="number">${state.ended?'—':CAPACITY-state.used} <small>/ 8 iniciales</small></div><div class="stat-foot">${state.ended?'Piloto finalizado':'Crecemos al ritmo de la capacidad'}</div></div><div class="stat verified"><div class="stat-top">Cierres verificados ${icon('shield')}</div><div class="number">${String(verified).padStart(2,'0')}</div><div class="stat-foot">Una visita por sí sola no cuenta</div></div></div>`}
function caseTable(list,full=false){return `<div class="card table-card"><div class="table-heading"><h2>${full?'Casos del piloto':'Casos en seguimiento'} <span>${list.length} hogares ficticios</span></h2>${!full?'<button class="btn ghost small" data-page="cases">Ver todos los casos →</button>':''}</div><div class="table-wrap"><table><thead><tr><th>HOGAR</th><th>ESTADO ACTUAL</th><th>PRÓXIMO PASO</th><th>ACTUALIZACIÓN</th><th aria-label="Abrir caso"></th></tr></thead><tbody>${list.map(c=>`<tr><td><div class="house-cell"><span class="house-icon">${icon('house')}</span>Hogar ${c.id}</div></td><td>${badge(c)}</td><td>${nextStep(c)}</td><td>${new Date(c.history[0].at).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})}</td><td><button class="arrowbutton" data-case="${c.id}" aria-label="Abrir hogar ${c.id}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="table-meta"><span>Sin nombres, direcciones ni datos personales.</span><span>Actualizado en esta sesión</span></div></div>`}
function nextStep(c){if(c.stage==='review'&&c.reviewDecision==='data')return 'Completar datos o revisión manual';if(c.stage==='review'&&c.reviewDecision==='monitor')return 'Mantener seguimiento';return ({new:'Revisar el caso',review:'Asignar visita',scheduled:'Registrar visita',visited:'Verificar resultado',verified:'Seguimiento disponible',funding:'Coordinar apoyo'})[c.stage]}
function chartCard(c,controls=false){const sig=signal(c);return `<div class="card"><div class="card-head"><div><div class="card-kicker">${c.stage==='verified'?'SERIE INICIAL · SOLO REFERENCIA':'LECTURAS DEL HOGAR '+c.id}</div><h2>El consumo, a la vista.</h2><p class="card-sub">Últimas 24 horas · Litros por intervalo de 15 minutos</p></div><div class="chart-head-right"><i></i>Serie de demostración</div></div><div class="chart-container">${chart(c.values)}</div><div class="chart-footer"><div class="legend"><i></i>Consumo de agua</div><span class="simulation-label">SENSOR SIMULADO</span></div><div class="case-insight ${sig.kind==='normal'?'normal':['insufficient','stale'].includes(sig.kind)?'data':''}">${icon(sig.kind==='normal'?'check':'alert')}<p><strong>${c.stage==='verified'?'Gráfica inicial de referencia':labels[sig.kind]}.</strong> ${c.stage==='verified'?'No fue la evidencia usada para el cierre. La comparación registrada se muestra en el resumen superior; esta serie conserva sus lecturas originales.':descriptions[sig.kind]}</p></div>${controls?`<div class="chart-control"><label for="scenario">Escenario de prueba</label><select id="scenario"><option value="leak" ${c.scenario==='leak'?'selected':''}>Posible fuga</option><option value="normal" ${c.scenario==='normal'?'selected':''}>Patrón normal</option><option value="insufficient" ${c.scenario==='insufficient'?'selected':''}>Datos insuficientes</option></select><button class="btn small ghost" data-action="scenario">Cargar escenario</button></div>`:''}</div>`}
function serviceCard(){return `<div class="card service-card"><h3>${icon('clock')}Atención con límites claros</h3><p>No hay atención real conectada. Fuera de horario no esperes respuesta del piloto.</p><button data-action="limits">Conocer horarios y alcance ↗</button></div>`}
function panel(){let c=ccase();return heading('Cada señal merece seguimiento.','Revisa lo que pasa. Acompaña hasta verificar.')+stats()+`<div class="dashboard-grid">${chartCard(c,true)}<div class="side-stack"><div class="card attention-card"><div class="section-label">${icon('activity')}CASO SELECCIONADO</div><div class="case-id">Hogar ${c.id}<small>Participante ficticio del piloto</small></div>${badge(c)}<p>${c.stage==='verified'?'El cierre incluye observación, lecturas comparables y confirmación ficticia.':'Una alerta abre una revisión. El caso sigue abierto hasta comprobar el resultado.'}</p><button class="btn primary" data-case="${c.id}">${c.stage==='new'?'Revisar caso':'Continuar seguimiento'} ${icon('arrow')}</button></div>${serviceCard()}</div></div>`+caseTable(state.cases.slice(0,4))+`<div class="flow-strip">${icon('shield')}<b>El recorrido importa</b><span>Señal → Revisión → Visita → Verificación</span><span>Una visita no significa caso resuelto.</span></div>`}
function casesPage(){const list=state.cases.filter(c=>filter==='all'||(filter==='verified'?c.stage==='verified':filter==='open'?c.stage!=='verified':c.stage==='scheduled'));return heading('Ningún caso se queda invisible.','Cada hogar tiene un siguiente paso claro.')+`<div class="filter-row">${[['all','Todos'],['open','Abiertos'],['scheduled','Con cita'],['verified','Verificados']].map(([a,b])=>`<button class="filter ${filter===a?'active':''}" data-filter="${a}">${b}</button>`).join('')}</div>`+(list.length?caseTable(list,true):'<div class="card empty">Aún no hay casos en este estado.</div>')}
const observationNames={'leak-fixed':'Se intervino una posible fuga','no-leak':'No se encontró una fuga durante la visita','needs-work':'El problema persiste o falta trabajo'};
const components={pipe:'Tubería o unión',tap:'Llave o grifo',toilet:'Sanitario',tank:'Depósito o tinaco',other:'Otro elemento revisado'};
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,a=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[a]));
function formatDate(at){return new Date(at).toLocaleString('es-MX',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function evidenceSummary(c){if(c.stage!=='verified'||!c.evidence)return '';const e=c.evidence;return `<section class="closure-summary" aria-labelledby="closure-title"><div class="closure-title">${icon('shield')}<div><div class="tag">RESUMEN DEL CIERRE · DATOS FICTICIOS</div><h2 id="closure-title">Qué se comprobó antes de cerrar</h2></div></div><dl><div><dt>Trabajo registrado</dt><dd>${observationNames[e.observation]}. ${c.component?components[c.component]+'.':'No se especificó el elemento intervenido.'}</dd></div><div><dt>Datos comparados</dt><dd>${e.before} L antes / ${e.after} L después.<br>Periodos de ${e.duration} minutos cada uno, en condiciones similares.</dd></div><div><dt>Periodo anterior</dt><dd>${formatDate(e.beforeStart)} a ${formatDate(e.beforeStart+e.duration*60000)}</dd></div><div><dt>Periodo posterior</dt><dd>${formatDate(e.afterStart)} a ${formatDate(e.afterStart+e.duration*60000)}</dd></div><div><dt>Fuente declarada</dt><dd>${e.source==='manual'?'Revisión manual de demostración':'Sensor simulado · comparación registrada por una persona'}</dd></div><div><dt>Confirmación de la familia</dt><dd>En esta prueba ficticia, confirmó que el problema dejó de observarse.</dd></div></dl><p>Una persona registró este cierre con la evidencia anterior. La gráfica inicial no es la evidencia de esta comparación. Si el problema continúa, se puede reabrir.</p></section>`}
function detail(){const c=ccase();return `<div class="page-heading case-heading"><div><button class="btn ghost small" data-page="cases">← Todos los casos</button><h1 style="margin-top:8px">Hogar ${c.id}</h1><p class="subtitle">Caso ficticio · Los cambios se borran al recargar o cerrar esta pestaña.</p></div>${badge(c)}</div><section class="next-action ${c.stage==='verified'?'is-verified':''}" aria-labelledby="next-title"><div><div class="tag">${c.stage==='verified'?'CIERRE REGISTRADO EN DEMO':'SIGUIENTE PASO'}</div><h2 id="next-title">${c.stage==='verified'?'Consultar la evidencia del cierre':nextStep(c)}</h2><p>${state.ended?'El piloto finalizó en esta demostración. Los pendientes siguen visibles.':c.stage==='verified'?'Puedes cuestionar el cierre si el problema continúa.':c.stage==='visited'?'La visita terminó; aún falta comparar datos y confirmar con la familia.':'Revisa el contexto humano. Las lecturas antiguas no confirman ni descartan una fuga.'}</p></div><div class="action-row">${caseButtons(c)}</div></section>${evidenceSummary(c)}<div class="detail-grid"><div><div class="card content-card"><h2>De la señal al cierre.</h2><div class="steps">${progress(c.stage).map(s=>`<div class="step ${s.state} ${c.stage==='verified'?'verified-step':''}"><i>${s.symbol}</i>${s.label}<small>${s.state==='current'?'Paso actual':s.state==='complete'?'Completado':'Pendiente'}</small></div>`).join('')}</div><p>${c.stage==='verified'?'Revisa arriba el trabajo, los periodos y la confirmación registrados.':'El paso azul es el actual. Las marcas indican pasos completados; el verde se reserva para el cierre verificado.'}</p></div><div style="margin-top:20px">${chartCard(c)}</div></div><div class="side-stack"><div class="card content-card"><div class="tag">REGISTRO DEL CASO</div><h2>Lo que sí ha ocurrido.</h2><ul class="history">${c.history.map(a=>`<li>${a.text}<time>${new Date(a.at).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit',second:'2-digit'})} · registro de demo</time></li>`).join('')}</ul></div>${serviceCard()}${c.appointment?`<div class="card content-card"><h3>${icon('calendar')} Visita de demostración</h3><p>Técnico ficticio ${c.appointment.technician}<br>Jornada simulada · ${c.appointment.slot}<br>${visitState(c)}</p>${c.observation?`<p><strong>Trabajo registrado:</strong> ${observationNames[c.observation]}. ${c.component?components[c.component]+'.':''}</p>`:''}</div>`:''}</div></div>`}
function verificationForm(c){const d=c.verificationDraft||{};const options=(items,value)=>items.map(([v,t])=>`<option value="${v}" ${v===String(value)?'selected':''}>${t}</option>`).join('');return `<p>Registra los periodos y el origen de la comparación. La visita y el análisis automático no bastan para cerrar. Todos los valores y confirmaciones son ficticios.</p><form id="verify-form"><div class="form-field"><label for="evidence-source">Fuente de las lecturas comparadas</label><select id="evidence-source" required>${options([['','Seleccionar…'],['manual','Revisión manual de demostración'],['sensor','Sensor simulado · fuente declarada']],d.source)}</select><small>La comparación se registra por separado. No se toma automáticamente de la gráfica inicial.</small></div><div class="form-field"><label for="period-duration">Duración de cada periodo</label><select id="period-duration" required>${options([['','Seleccionar…'],['15','15 minutos cada uno'],['30','30 minutos cada uno'],['60','60 minutos cada uno']],d.duration)}</select></div><div class="form-row"><div class="form-field"><label for="before-start">Inicio del periodo anterior</label><input id="before-start" type="datetime-local" value="${escapeHtml(d.beforeStart)}" max="${localDate()}" required></div><div class="form-field"><label for="after-start">Inicio del periodo posterior</label><input id="after-start" type="datetime-local" value="${escapeHtml(d.afterStart)}" max="${localDate()}" required></div></div><div class="form-row"><div class="form-field"><label for="before">Antes (L)</label><input id="before" type="number" min="0" max="10000" step="0.01" value="${escapeHtml(d.before)}" placeholder="Ej. 100" required></div><div class="form-field"><label for="after">Después (L)</label><input id="after" type="number" min="0" max="10000" step="0.01" value="${escapeHtml(d.after)}" placeholder="Ej. 20" required></div></div><label class="check-label"><input type="checkbox" id="comparable" ${d.comparable?'checked':''} required>Confirmo que comparé periodos de la misma duración y condiciones similares (demostración).</label><div class="form-field"><label for="family">Confirmación ficticia de la familia</label><select id="family" required>${options([['','Seleccionar…'],['yes','El problema dejó de observarse'],['no','Sigue ocurriendo o no está de acuerdo'],['unknown','Aún no se pudo comprobar']],d.confirmation)}</select></div>${error}<div class="dialog-actions"><button class="btn" type="button" data-action="save-pending">Guardar pendiente</button><button class="btn primary" type="submit">Registrar verificación</button></div></form>`}
function readEvidenceForm(){return {source:$('#evidence-source').value,duration:$('#period-duration').value,beforeStart:$('#before-start').value,afterStart:$('#after-start').value,before:$('#before').value,after:$('#after').value,comparable:$('#comparable').checked,confirmation:$('#family').value}}

function caseButtons(c){if(state.ended)return '<button class="btn warn" data-action="end">Ver plan de cierre del piloto</button>';if(c.stage==='verified')return '<button class="btn" data-action="reopen">El problema continúa</button>';if(c.stage==='new')return '<button class="btn primary" data-action="review">Revisar el caso '+icon('arrow')+'</button><button class="btn" data-action="manual">Registrar lectura</button>';if(c.stage==='review'&&['data','monitor'].includes(c.reviewDecision))return '<button class="btn primary" data-action="review">Revisar de nuevo</button><button class="btn" data-action="manual">Registrar lectura</button>';if(c.stage==='review'||c.stage==='funding')return '<button class="btn primary" data-action="book">Asignar visita '+icon('calendar')+'</button><button class="btn" data-action="funding">Falta apoyo o financiamiento</button>';if(c.stage==='scheduled')return '<button class="btn primary" data-action="visit">Registrar visita</button>';return '<button class="btn primary" data-action="verify">Verificar resultado '+icon('check')+'</button><button class="btn" data-action="reopen">Solicitar segunda revisión</button>'}
function appointments(){const all=state.cases.filter(c=>c.appointment);return heading('La capacidad también se cuida.','Ocho cupos iniciales. Cada visita, incluidas las de seguimiento, ocupa capacidad.',null)+stats()+`<div class="card content-card"><h2>Agenda de la jornada simulada</h2><p>Los técnicos y horarios son ficticios. Una cita aquí no contacta a nadie ni confirma un servicio real.</p>${all.length?all.sort((a,b)=>a.appointment.slot.localeCompare(b.appointment.slot)).map(c=>`<div class="agenda-item"><div class="agenda-time">${c.appointment.slot}</div><div>Hogar ${c.id}<small>Técnico ficticio ${c.appointment.technician} · ${c.appointment.done?'Visita registrada':'Cita pendiente'}</small></div><button class="btn small" data-case="${c.id}">Abrir caso →</button></div>`).join(''):`<div class="empty">${icon('calendar')}<h2>Espacio para dar seguimiento.</h2><p>Aún no hay citas. Revisa un caso antes de asignar una visita.</p><button class="btn primary" data-page="cases" style="margin-top:18px">Ir a los casos</button></div>`}</div>`}
function modelPage(){const m=model.metrics;return heading('Una señal, no un diagnóstico.','ML real, entrenado exclusivamente con hogares sintéticos.',null)+`<div class="detail-grid"><div>${chartCard(ccase(),true)}<div class="card content-card" style="margin-top:20px"><h2>¿Qué mira el modelo?</h2><p>Promedio de consumo nocturno, variación durante el día y duración del consumo continuo. Una regresión logística combina estos patrones aprendidos para señalar una posible anomalía.</p><p>Si faltan lecturas o tienen más de 24 horas, el modelo no evalúa la serie. La decisión sobre el caso siempre requiere revisión humana.</p><button class="btn" data-action="manual" style="margin-top:15px">${icon('plus')}Registrar lectura manual</button></div></div><div class="card content-card"><div class="tag">${model.version}</div><h2>Evaluación sintética</h2><div class="model-stats"><div><strong>${Math.round(m.precision*100)}%</strong><small>Precisión</small></div><div><strong>${Math.round(m.recall*100)}%</strong><small>Recall</small></div></div><div class="notice">Estos resultados solo describen el conjunto sintético reservado. No demuestran exactitud en hogares reales.</div><p>800 hogares sintéticos para entrenamiento.<br>200 hogares distintos para evaluación.<br>Semilla reproducible: ${model.seed}.</p><table class="metric-table"><tbody><tr><th>RESULTADO</th><th>CASOS</th></tr><tr><td>Anomalías detectadas</td><td>${m.true_positive}</td></tr><tr><td>Normales identificados</td><td>${m.true_negative}</td></tr><tr><td>Falsas alertas</td><td>${m.false_positive}</td></tr><tr><td>Anomalías omitidas</td><td>${m.false_negative}</td></tr></tbody></table><p>Este puntaje no confirma una fuga ni garantiza seguridad.</p><a class="btn small" href="model.json" target="_blank" rel="noopener" style="margin-top:15px">Ver ficha del modelo ↗</a></div></div>`}
function about(){return heading('Tecnología con responsabilidad.','Un piloto pequeño que muestra sus límites desde el inicio.',null)+`<div class="about-grid"><div class="card content-card"><div class="tag">EL PROPÓSITO</div><h2>Detectar es solo el principio.</h2><p>Agua en seguimiento conecta una señal de consumo con revisión, capacidad de visita y comprobación del resultado. Crecer solo tiene sentido si podemos resolver y verificar.</p><p>Proyecto académico de Isabella Zevada · Week 11. Vacío propuesto: Household water tools. El Blueprint final del equipo y su shadow clause exacta siguen pendientes de cotejo.</p><a class="btn" href="packet.pdf" target="_blank" rel="noopener" style="margin-top:18px">${icon('file')}Leer packet en inglés ↗</a></div><div class="card content-card"><div class="tag">QUÉ ES REAL Y QUÉ ES SIMULADO</div><h2>Sin confundir demostración con servicio.</h2><p>El modelo matemático sí se entrena y se ejecuta. Sensores, hogares, técnicos, lecturas y resultados de reparación son inventados. No hay personas atendiendo alertas, envío de mensajes ni conexiones a dispositivos.</p><p>Los cambios viven solo en la memoria de esta pestaña. Si recargas, el demo se reinicia. No escribas ni cargues datos personales.</p><button class="btn" data-action="limits" style="margin-top:18px">${icon('info')}Ver alcance y horarios</button></div><div class="card content-card"><div class="tag">LÍMITE ÉTICO</div><h2>La familia puede cuestionar el cierre.</h2><p>Ninguna alerta, respuesta automática, visita o falta de datos se presentará como atención efectiva, seguridad o reparación comprobada. Se conserva una alternativa manual y no se venden datos, vigilan hábitos ni hacen cortes automáticos.</p></div><div class="card content-card"><div class="tag">CONTROLES DE DEMOSTRACIÓN</div><h2>Ensaya también el final.</h2><p>Si se termina el financiamiento, los casos pendientes siguen visibles. La familia debe saber cuándo termina el monitoreo y qué pasará con equipos y seguimiento.</p><div class="action-row"><button class="btn warn" data-action="end">Simular fin del piloto</button><button class="btn" data-action="reset">Reiniciar demo</button></div></div></div>`}
function render(){const names={panel:'Panel general',cases:'Casos del piloto',appointments:'Agenda de visitas',model:'Lecturas y modelo',detail:'Detalle del caso',about:'Acerca del piloto'};$('#breadcrumb').textContent=names[page]||names.panel;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===(page==='detail'?'cases':page)));$('#app').innerHTML=(state.ended?'<div class="notice" style="margin:0 0 20px">Piloto finalizado en esta demostración. No se aceptan nuevas citas ni se mantiene monitoreo real. Los pendientes siguen visibles. <button class="btn ghost small" data-action="end">Ver plan de cierre →</button></div>':'')+({panel,cases:casesPage,detail,appointments,model:modelPage,about}[page]||panel)();decorate()}
function openDialog(title,sub,body){$('#dialog-content').innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${title}</h2><p>${sub}</p></div><button class="iconbutton" data-action="dismiss" aria-label="Cerrar ventana">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;$('#dialog').showModal()}
const error='<p id="form-error" class="error" role="alert"></p>';
const actions=(text)=>`<div class="dialog-actions"><button type="button" class="btn" data-action="dismiss">Cancelar</button><button class="btn primary" type="submit">${text}</button></div>`;
function showError(t){$('#form-error').textContent=t}
function localDate(){const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset()-1);return d.toISOString().slice(0,16)}
function act(action){let c=ccase();if(action==='dismiss'){$('#dialog').close();return}if(action==='limits'){openDialog('Horarios y alcance','Demostración académica · sin atención real',`<div class="danger-note">Ante una urgencia, busca atención externa sin esperar respuesta de este piloto. No hay atención real conectada a esta página.</div><p>El proveedor, su cobertura, el costo y los horarios deben verificarse antes de un piloto real. No mostramos teléfonos ni servicios inventados.</p><p>Una confirmación automática solo significa que un reporte fue recibido; no equivale a que alguien lo revisó o atendió. En este demo solo se registran acciones de prueba.</p><p>Los ocho cupos pertenecen a una jornada ficticia y no son una promesa de atención semanal.</p><div class="dialog-actions"><button class="btn primary" data-action="dismiss">Entendido</button></div>`);return}if(action==='reset'){openDialog('¿Reiniciar la demostración?','Se borran únicamente cambios ficticios de esta sesión.',`<p>Se restaurarán los 12 hogares y los ocho cupos iniciales. No hay datos guardados en un servidor.</p><div class="dialog-actions"><button class="btn" data-action="dismiss">Conservar cambios</button><button class="btn primary" data-action="confirm-reset">Sí, reiniciar</button></div>`);return}if(action==='confirm-reset'){state=makeState();selected='H-03';page='panel';$('#dialog').close();render();toast('Demostración reiniciada. No hay datos reales.');return}if(action==='scenario'){const sc=$('#scenario').value;c.scenario=sc;c.values=[...scenarios[sc]];c.updatedAt=Date.now();log(c,'Se cargó un escenario de lecturas simuladas.');render();toast('Lecturas simuladas actualizadas. El estado del seguimiento se conserva.');return}if(action==='manual'){openDialog('Registrar lectura manual',`Hogar ficticio ${c.id} · litros por intervalo de 15 minutos`,`<p>Esta lectura se agrega al registro manual, sin sustituir la serie del sensor. Una sola lectura no permite evaluar un patrón temporal.</p><form id="manual-form"><div class="form-field"><label for="reading">Litros del intervalo</label><input id="reading" name="reading" type="number" min="0" max="10000" step="0.01" required placeholder="Ej. 12.5"><small>Solo números entre 0 y 10,000. Sin información personal.</small></div><div class="form-field"><label for="read-date">Fecha y hora del intervalo</label><input id="read-date" name="date" type="datetime-local" max="${localDate()}" value="${localDate()}" required></div>${error}${actions('Agregar lectura')}</form>`);return}if(action==='review'){openDialog('Revisar el caso',`Hogar ${c.id} · decide con contexto humano`,`<p>${descriptions[signal(c).kind]} La prioridad se revisa por necesidad y urgencia, sin excluir a quien no use una app.</p><form id="review-form"><div class="form-field"><label for="review-result">Resultado de la revisión ficticia</label><select id="review-result" required><option value="">Seleccionar…</option><option value="visit">Requiere visita técnica</option><option value="data">Faltan datos: pedir revisión manual</option><option value="monitor">Uso explicado: mantener seguimiento</option></select></div>${error}${actions('Registrar revisión')}</form>`);return}if(action==='book'){openDialog('Asignar visita de demostración',`${CAPACITY-state.used} cupos disponibles · no se contacta a nadie`,`<p>La jornada y los técnicos son ficticios. Una segunda visita ocupa también un cupo. No se asigna un horario ocupado.</p><form id="booking-form"><div class="form-row"><div class="form-field"><label for="technician">Técnico ficticio</label><select id="technician" required><option value="">Seleccionar…</option><option value="T-01">Técnico T-01</option><option value="T-02">Técnico T-02</option></select></div><div class="form-field"><label for="slot">Horario simulado</label><select id="slot" required><option value="">Seleccionar…</option>${['09:00','10:00','11:00','12:00'].map(s=>`<option>${s}</option>`).join('')}</select></div></div>${error}${actions('Confirmar cita ficticia')}</form>`);return}if(action==='visit'){openDialog('Registrar visita realizada',`Hogar ${c.id} · una visita no significa resolución`,`<form id="visit-form"><div class="form-field"><label for="visit-result">Observación técnica ficticia</label><select id="visit-result" required><option value="">Seleccionar…</option><option value="leak-fixed">Se intervino una posible fuga</option><option value="no-leak">No se encontró fuga; requiere comprobación</option><option value="needs-work">El problema persiste o falta trabajo</option></select></div><div class="form-field"><label for="visit-component">Elemento revisado o intervenido</label><select id="visit-component" required><option value="">Seleccionar…</option>${Object.entries(components).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div><p class="notice">Después hay que comparar lecturas y confirmar el resultado con la familia.</p>${error}${actions('Registrar visita')}</form>`);return}if(action==='verify'){openDialog('Verificar antes de cerrar',`Hogar ${c.id} · comprobación ficticia`,verificationForm(c));return}if(action==='save-pending'){const draft=readEvidenceForm();if([draft.before,draft.after].some(v=>v!==''&&(!Number.isFinite(Number(v))||Number(v)<0||Number(v)>10000))){showError('Usa lecturas entre 0 y 10,000 L o deja el dato vacío.');return}c.verificationDraft=draft;log(c,'Verificación guardada como pendiente. No se ha comprobado el cierre.');$('#dialog').close();render();toast('Guardado pendiente en esta sesión. El caso sigue abierto.');return}if(action==='funding'){c.stage='funding';log(c,'Pendiente de apoyo o canalización con seguimiento. Sin cobro automático a la familia.');render();toast('El caso sigue abierto. No se cuenta como resuelto.');return}if(action==='reopen'){c.stage='review';c.reviewDecision='visit';log(c,'Se solicitó segunda revisión. El hogar puede cuestionar el cierre.');render();toast('Caso reabierto. La segunda visita requiere cupo.');return}if(action==='end'){const pending=state.cases.filter(c=>c.stage!=='verified').length;openDialog('Plan de cierre del piloto',`${pending} casos ficticios pendientes · deben seguir visibles`,`<p>Antes del fin de un piloto real, se debe avisar con anticipación y acordar con cada familia:</p><ul style="font-size:12px;color:#71887a;line-height:2"><li>Fecha de fin del monitoreo.</li><li>Qué ocurrirá con los equipos.</li><li>Quién dará seguimiento a cada caso pendiente.</li><li>Una ruta externa comprobada, con costo y cobertura claros.</li></ul><div class="danger-note">Esta página no presta monitoreo real. La ruta externa aún no está confirmada.</div><div class="dialog-actions"><button class="btn" data-action="dismiss">Volver</button>${!state.ended?'<button class="btn warn" data-action="confirm-end">Simular fin del piloto</button>':''}</div>`);return}if(action==='confirm-end'){state.ended=true;state.cases.forEach(c=>{if(c.stage!=='verified')log(c,'Piloto finalizado en la demostración. Caso pendiente, sin cierre falso.')});$('#dialog').close();render();toast('Piloto finalizado en el demo; los pendientes siguen visibles.')}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.page){e.preventDefault();go(b.dataset.page)}else if(b.dataset.case){selected=b.dataset.case;go('detail')}else if(b.dataset.action)act(b.dataset.action);else if(b.dataset.filter){filter=b.dataset.filter;render()}});
document.addEventListener('submit',e=>{if(!e.target.closest('dialog'))return;e.preventDefault();const c=ccase();if(state.ended){showError('El piloto está finalizado en el demo. Reinícialo para crear acciones nuevas.');return}let msg=null;if(e.target.id==='manual-form'){const value=$('#reading').value,date=$('#read-date').value;msg=validateReading(value,date,c.manual);if(!msg){c.manual.push({value:Number(value),at:new Date(date).getTime()});log(c,`Lectura manual ficticia añadida: ${Number(value)} L. No se ejecutó inferencia con una lectura aislada.`)}}if(e.target.id==='review-form'){const decision=$('#review-result').value;if(!decision)msg='Selecciona un resultado.';else{c.stage='review';c.reviewDecision=decision;log(c,({visit:'Revisión humana de demo: se requiere visita técnica.',data:'Revisión humana de demo: datos pendientes y alternativa manual.',monitor:'Uso explicado en demo. Se mantiene seguimiento; no hay cierre verificado.'})[decision])}}if(e.target.id==='booking-form'){msg=book(state,c.id,$('#technician').value,$('#slot').value);if(!msg)log(c,`Cita ficticia asignada a ${c.appointment.technician}, jornada simulada a las ${c.appointment.slot}.`)}if(e.target.id==='visit-form'){const obs=$('#visit-result').value;if(!obs||!$('#visit-component').value)msg='Selecciona la observación y el elemento revisado.';else{c.component=$('#visit-component').value;c.observation=obs;c.stage='visited';c.appointment.done=true;log(c,`Visita ficticia registrada: ${observationNames[obs]}. ${components[c.component]}. Resultado todavía no verificado.`)}}if(e.target.id==='verify-form'){const d=readEvidenceForm();c.verificationDraft=d;const oldStage=c.stage;msg=closeCase(c,c.observation,d.before,d.after,d.confirmation,d);if(c.stage==='review'&&oldStage!==c.stage){c.reviewDecision='visit';log(c,'La verificación no permite cierre: se requiere segunda revisión.');$('#dialog').close();render();toast(msg);return}if(!msg){c.verificationDraft=null;log(c,'Cierre verificado en demo: trabajo registrado, periodos comparados y confirmación ficticia de la familia.')}}if(msg){showError(msg);return}$('#dialog').close();render();toast('Acción ficticia registrada en esta sesión.');});
window.addEventListener('hashchange',()=>{const allowed=['panel','cases','appointments','model','about','detail'];let p=location.hash.slice(1);if(allowed.includes(p)&&p!==page){page=p;render()}});
try{[model,scenarios]=await Promise.all(['model.json','scenarios.json'].map(async f=>{const r=await fetch(f);if(!r.ok)throw Error(f);return r.json()}));state=makeState();const p=location.hash.slice(1);if(['panel','cases','appointments','model','about'].includes(p))page=p;render()}catch(e){$('#app').innerHTML='<div class="loading-error"><h1>No se pudo cargar el demo.</h1><p>Recarga la página para intentar de nuevo. No se guardaron datos personales.</p><button class="btn" onclick="location.reload()">Reintentar</button></div>';console.error('Unable to load synthetic demo assets')}
